/* menu/src/biosid.c -- see biosid.h. Rows generated by `py -m omsat.biosid` from D:\Sega Saturn BIOS;
 * tools/tests/test_biosid.py keeps the two tables equal. BSD-3-Clause. */
#include "biosid.h"
#include "om_fmt.h"
static const om_bios_id k_bios[] = {
    { 0x2aba43c2u, "SATURN 1.00 J", OM_BIOS_JP },
    { 0x224b752cu, "SATURN 1.01 J", OM_BIOS_JP },
    { 0xb3c63c25u, "SATURN 1.003 J", OM_BIOS_JP },
    { 0xe4d61811u, "V-SATURN 1.01 J", OM_BIOS_JP },
    { 0x721e1b60u, "HI-SATURN 1.01 J", OM_BIOS_JP },
    { 0x3408dbf4u, "HI-SATURN 1.02 J", OM_BIOS_JP },
    { 0x6abfefeau, "GAMENAVI 1.03", OM_BIOS_OTHER },
    { 0xf90f0089u, "SATURN 1.00A U", OM_BIOS_US },
    { 0x4afcf0fau, "SATURN 1.01A U/EUR", OM_BIOS_US },
};
const om_bios_id *om_bios_lookup(uint32_t crc)
{
    uint32_t i;
    for (i = 0; i < sizeof k_bios / sizeof k_bios[0]; i++) if (k_bios[i].crc == crc) return &k_bios[i];
    return 0;
}
uint32_t om_bios_crc(const volatile uint8_t *rom, uint32_t len)
{
    uint8_t buf[256];
    uint32_t crc = 0, o, i;
    for (o = 0; o < len; o += sizeof buf) {
        for (i = 0; i < sizeof buf; i++) buf[i] = rom[o + i];
        crc = om_crc32(crc, buf, sizeof buf);
    }
    return crc;
}
